import{_ as e,c as i,o as s,ae as r}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"Política de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy-policy.md","filePath":"es/guide/privacy-policy.md","lastUpdated":1795170900000}'),o={name:"es/guide/privacy-policy.md"};function n(t,a,c,l,d,u){return s(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="politica-de-privacidad" tabindex="-1">Política de privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to &quot;Política de privacidad&quot;">​</a></h1><p>Qué recopila Persim y qué permanece en tu dispositivo.</p><h2 id="sin-cuenta-sin-perfil-en-la-nube" tabindex="-1">Sin cuenta, sin perfil en la nube <a class="header-anchor" href="#sin-cuenta-sin-perfil-en-la-nube" aria-label="Permalink to &quot;Sin cuenta, sin perfil en la nube&quot;">​</a></h2><p>Persim no te pide iniciar sesión ni crea una cuenta en línea. El historial, los marcadores, las pestañas abiertas, las descargas y las cookies se guardan en tu Mac.</p><h2 id="informacion-para-mostrar-paginas" tabindex="-1">Información para mostrar páginas <a class="header-anchor" href="#informacion-para-mostrar-paginas" aria-label="Permalink to &quot;Información para mostrar páginas&quot;">​</a></h2><p>Como cualquier navegador, Persim envía las direcciones que visitas a los sitios que abres. Persim no sube tu historial de navegación a ningún servidor.</p><h2 id="funciones-de-red-que-puedes-activar" tabindex="-1">Funciones de red que puedes activar <a class="header-anchor" href="#funciones-de-red-que-puedes-activar" aria-label="Permalink to &quot;Funciones de red que puedes activar&quot;">​</a></h2><ul><li>Las suscripciones de bloqueo de anuncios actualizan sus listas por la red. Si falla la actualización, la lista guardada sigue funcionando.</li><li>Los userscripts y los archivos que descargas se obtienen solo cuando lo pides.</li><li>Al escribir en la barra de direcciones, las sugerencias llegan del motor de búsqueda elegido.</li></ul><h2 id="permisos-locales" tabindex="-1">Permisos locales <a class="header-anchor" href="#permisos-locales" aria-label="Permalink to &quot;Permisos locales&quot;">​</a></h2><p>La cámara, el micrófono y el acceso a archivos se recuerdan por sitio y se pueden cambiar en los ajustes. La ubicación y las notificaciones las controla macOS. Una ventana privada (⌘⇧N) no deja rastro en el historial ni en la sesión.</p><h2 id="sitios-de-terceros" tabindex="-1">Sitios de terceros <a class="header-anchor" href="#sitios-de-terceros" aria-label="Permalink to &quot;Sitios de terceros&quot;">​</a></h2><p>Los sitios que visitas son operados por otros y siguen sus propias políticas de privacidad. Las páginas integradas de Persim no te rastrean.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Preguntas sobre privacidad: <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',14)])])}const h=e(o,[["render",n]]);export{m as __pageData,h as default};
